import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_OH 16
#define TILE_OW 16
#define OC_TILE 32
#define OW_PER_THREAD 2
#define BLOCK_X (TILE_OW / OW_PER_THREAD)
__device__ __forceinline__ void load_channel_tile(
    const float* __restrict__ in_batch,
    const float* __restrict__ weight,
    float* __restrict__ s_in,
    float* __restrict__ s_w,
    int c, int C_in, int H, int W,
    int in_h0, int in_w0, int in_tile_w, int total,
    int tid, int nthreads, int wk_total,
    int oc_base, int C_out, int KH, int KW)
{
    const float* in_c = in_batch + (size_t)c * H * W;
    for (int idx = tid; idx < total; idx += nthreads) {
        int r = idx / in_tile_w;
        int cc = idx % in_tile_w;
        int ih = in_h0 + r;
        int iw = in_w0 + cc;
        float val = 0.0f;
        if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
            val = in_c[(size_t)ih * W + iw];
        }
        s_in[idx] = val;
    }
    for (int idx = tid; idx < wk_total; idx += nthreads) {
        int i = idx / (KH * KW);
        int rem = idx % (KH * KW);
        int oc = oc_base + i;
        float wval = 0.0f;
        if (oc < C_out) {
            wval = weight[((size_t)oc * C_in + c) * KH * KW + rem];
        }
        s_w[idx] = wval;
    }
}
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int KH, int KW,
    int stride, int padH, int padW,
    int dilH, int dilW,
    int H_out, int W_out,
    int in_tile_h, int in_tile_w,
    int oc_groups)
{
    extern __shared__ float smem[];
    size_t in_tile_size = (size_t)in_tile_h * (size_t)in_tile_w;
    size_t w_tile_size = (size_t)OC_TILE * KH * KW;
    float* s_in_buf[2];
    float* s_w_buf[2];
    s_in_buf[0] = smem;
    s_w_buf[0] = smem + in_tile_size;
    s_in_buf[1] = s_w_buf[0] + w_tile_size;
    s_w_buf[1] = s_in_buf[1] + in_tile_size;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int ow0 = blockIdx.x * TILE_OW;
    int oh0 = blockIdx.y * TILE_OH;
    int oh = oh0 + ty;
    int nc = blockIdx.z;
    int n = nc / oc_groups;
    int oc_group = nc % oc_groups;
    int oc_base = oc_group * OC_TILE;
    int in_h0 = oh0 * stride - padH;
    int in_w0 = ow0 * stride - padW;
    float sum[OC_TILE][OW_PER_THREAD];
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) {
        #pragma unroll
        for (int j = 0; j < OW_PER_THREAD; ++j) sum[i][j] = 0.0f;
    }
    int total = in_tile_h * in_tile_w;
    int tid = ty * BLOCK_X + tx;
    int nthreads = TILE_OH * BLOCK_X;
    int wk_total = OC_TILE * KH * KW;
    const float* in_batch = input + (size_t)n * C_in * H * W;
    bool oh_valid = (oh < H_out);
    int ow_local[OW_PER_THREAD];
    bool ow_valid[OW_PER_THREAD];
    #pragma unroll
    for (int j = 0; j < OW_PER_THREAD; ++j) {
        int ow = ow0 + tx * OW_PER_THREAD + j;
        ow_local[j] = ow;
        ow_valid[j] = (ow < W_out) && oh_valid;
    }
    if (C_in > 0) {
        load_channel_tile(in_batch, weight, s_in_buf[0], s_w_buf[0],
            0, C_in, H, W, in_h0, in_w0, in_tile_w, total,
            tid, nthreads, wk_total, oc_base, C_out, KH, KW);
    }
    __syncthreads();
    for (int c = 0; c < C_in; ++c) {
        int cur = c & 1;
        int nxt = cur ^ 1;
        if (c + 1 < C_in) {
            load_channel_tile(in_batch, weight, s_in_buf[nxt], s_w_buf[nxt],
                c + 1, C_in, H, W, in_h0, in_w0, in_tile_w, total,
                tid, nthreads, wk_total, oc_base, C_out, KH, KW);
        }
        float* s_in = s_in_buf[cur];
        float* s_w = s_w_buf[cur];
        for (int kh = 0; kh < KH; ++kh) {
            int sh = ty * stride + kh * dilH;
            const float* srow = s_in + (size_t)sh * in_tile_w;
            for (int kw = 0; kw < KW; ++kw) {
                float in_val[OW_PER_THREAD];
                #pragma unroll
                for (int j = 0; j < OW_PER_THREAD; ++j) {
                    int sw = (tx * OW_PER_THREAD + j) * stride + kw * dilW;
                    in_val[j] = srow[sw];
                }
                int wk_off = kh * KW + kw;
                #pragma unroll
                for (int i = 0; i < OC_TILE; ++i) {
                    int oc = oc_base + i;
                    if (oc < C_out) {
                        float wv = s_w[(size_t)i * KH * KW + wk_off];
                        #pragma unroll
                        for (int j = 0; j < OW_PER_THREAD; ++j) {
                            sum[i][j] += in_val[j] * wv;
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) {
        int oc = oc_base + i;
        if (oc < C_out) {
            #pragma unroll
            for (int j = 0; j < OW_PER_THREAD; ++j) {
                if (ow_valid[j]) {
                    output[((size_t)(n * C_out + oc) * H_out + oh) * W_out + ow_local[j]] = sum[i][j];
                }
            }
        }
    }
}
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padH, int padW,
    int dilH, int dilW)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int KH = weight.size(2);
    int KW = weight.size(3);
    int H_out = (H + 2 * padH - dilH * (KH - 1) - 1) / stride + 1;
    int W_out = (W + 2 * padW - dilW * (KW - 1) - 1) / stride + 1;
    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());
    int in_tile_h = (TILE_OH - 1) * stride + dilH * (KH - 1) + 1;
    int in_tile_w = (TILE_OW - 1) * stride + dilW * (KW - 1) + 1;
    size_t shmem_bytes = 2 * ((size_t)in_tile_h * (size_t)in_tile_w * sizeof(float) + (size_t)OC_TILE * KH * KW * sizeof(float));
    int oc_groups = (C_out + OC_TILE - 1) / OC_TILE;
    dim3 block(BLOCK_X, TILE_OH, 1);
    dim3 grid(
        (W_out + TILE_OW - 1) / TILE_OW,
        (H_out + TILE_OH - 1) / TILE_OH,
        N * oc_groups
    );
    if (shmem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(conv2d_forward_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, shmem_bytes);
    }
    conv2d_forward_kernel<<<grid, block, shmem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, KH, KW,
        stride, padH, padW,
        dilH, dilW,
        H_out, W_out,
        in_tile_h, in_tile_w,
        oc_groups
    );
    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padH, int padW,
    int dilH, int dilW);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 2D convolution operation with square input and asymmetric kernel,
    with dilation and padding, implemented via a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1,
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super(ModelNew, self).__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.has_bias = bias

        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kernel_size[0], kernel_size[1]))

        # Match nn.Conv2d default initialization
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = in_channels * kernel_size[0] * kernel_size[1]
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        out = conv2d_module.conv2d_forward_cuda(
            x, weight,
            self.stride,
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1]
        )

        if self.has_bias:
            out = out + self.bias.view(1, -1, 1, 1)

        return out


batch_size = 8
in_channels = 32
out_channels = 64
kernel_size = (5, 9)
width = 512
height = 512
stride = 1
padding = (2, 4)
dilation = (2, 3)


def get_inputs():
    x = torch.rand(batch_size, in_channels, height, width)
    return [x]


def get_init_inputs():
    return [in_channels, out_channels, kernel_size, stride, padding, dilation]

